mapper.select:
SELECT id, task_id, user_id, post_id, user_name, content,
       department_id, department_name, user_nick, seqid, msg_file_id,
       is_deleted, gmt_modified, gmt_created
FROM `tb_task_response`


        and task_id = #{taskId}


        and user_id = #{userId}


        and post_id = #{postId}




ORDER BY gmt_modified DESC

SELECT count( 1 ) FROM tb_task tt LEFT JOIN tb_collaboration_post tcp ON tt.post_id = tcp.id WHERE tcp.deleted = 0 AND tt.reply = 1
AND tt.user_id = #{userId}
and tt.post_id IN
#{postId}
AND tt.user_id IN
#{id}
AND tt.gmt_modified >= #{startTime}
AND tt.gmt_modified <= CONCAT(#{endTime}, ' 23:59:59')

SELECT r.id, r.task_id, r.user_id, r.user_name, r.department_id, r.department_name, r.post_id, r.gmt_created, r.seqid, p.post_name FROM tb_task_response r LEFT JOIN tb_collaboration_post p ON r.post_id = p.id
(r.gmt_created, r.id) > (#{timeAfter}, #{idAfter})
ORDER BY r.gmt_created ASC, r.id ASC LIMIT #{pageSize}
